import bpy
w = bpy.data.worlds.new("tmpw"); w.use_nodes = True
sn = w.node_tree.nodes.new('ShaderNodeTexSky')
props = {p.identifier: (p.type, getattr(sn, p.identifier, None)) for p in sn.bl_rna.properties if not p.is_hidden}
# filter readable scalar/enum/vector
out = {}
for k,(t,v) in props.items():
    if t in ('FLOAT','INT','BOOLEAN','ENUM'):
        out[k] = v
    elif t == 'FLOAT_VECTOR':
        out[k] = list(v) if v is not None else None
result = out
bpy.data.worlds.remove(w)

import bpy
w = bpy.data.worlds.new("tmpw"); w.use_nodes = True
sn = w.node_tree.nodes.new('ShaderNodeTexSky')
result = {}
for p in sn.bl_rna.properties:
    if p.is_hidden:
        continue
    if p.type in ('FLOAT','INT','BOOLEAN','ENUM'):
        try:
            result[p.identifier] = getattr(sn, p.identifier)
        except Exception as e:
            result[p.identifier] = "ERR:"+str(e)
bpy.data.worlds.remove(w)
result

import bpy, numpy as np, os
# A) material/object audit
audit = {}
for o in bpy.data.objects:
    if o.type == 'MESH':
        slots = [(ms.name, ms.material.name if ms.material else None) for ms in o.material_slots]
        audit[o.name] = slots
mats = {}
for m in bpy.data.materials:
    if m.use_nodes:
        bsdf = m.node_tree.nodes.get('Principled BSDF')
        d = {}
        if bsdf:
            for k in ['Base Color','Roughness','Metallic','IOR','Transmission Weight','Specular IOR Level']:
                if k in bsdf.inputs:
                    v = bsdf.inputs[k].default_value
                    d[k] = [round(float(x),3) for x in v] if hasattr(v,'__len__') else round(float(v),3)
        mats[m.name] = d
result = {"objects": audit, "materials": mats}

